export function findById(id) { return LAB_TESTS.find(x => x.id === id); }
export function search(q) {
  const s = String(q||'').toLowerCase();
  if (!s) return LAB_TESTS.slice();
  return LAB_TESTS.filter(x => JSON.stringify(x).toLowerCase().includes(s));
}
export function bySpecialty(spec) {
  return LAB_TESTS.filter(x => (x.specialty||x.category||'').toLowerCase() === String(spec||'').toLowerCase());
}
export function enabledOnly() { return LAB_TESTS.filter(x => x.enabled !== false); }
